Below is a minimal, self‑contained Go program that implements a simple in‑memory task manager with a REST API. It supports the four basic operations you asked for:

| Method | Path            | Action                              |
|--------|-----------------|-------------------------------------|
| `GET`  | `/{{p:entity}}`        | List all {{p:entity}}                      |
| `GET`  | `/{{p:entity}}/{id}`   | Get a single task by its ID         |
| `POST` | `/{{p:entity}}`        | Create a new task (JSON body)       |
| `DELETE`| `/{{p:entity}}/{id}`  | Delete a task by its ID             |

The {{p:entity}} are stored in a slice protected by a `sync.Mutex`, so the server is safe for concurrent access. The program uses only the Go standard library.

```go
// File: main.go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strconv"
	"strings"
	"sync"
)

// Task represents a single to‑do item.
type Task struct {
	ID        int    `json:"id"`        // unique identifier
	Title     string `json:"title"`     // short description
	Completed bool   `json:"completed"` // completion flag
}

// store holds the in‑memory task list and a mutex for safe concurrent access.
type store struct {
	sync.Mutex
	{{p:entity}} []Task
	nextID int
}

// newStore creates an empty store.
func newStore() *store {
	return &store{
		{{p:entity}}:  make([]Task, 0),
		nextID: 1,
	}
}

// list{{p:entity:title}} handles GET /{{p:entity}}
func (s *store) list{{p:entity:title}}(w http.ResponseWriter, r *http.Request) {
	s.Lock()
	defer s.Unlock()

	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(s.{{p:entity}}); err != nil {
		http.Error(w, "failed to encode {{p:entity}}", http.StatusInternalServerError)
	}
}

// getTask handles GET /{{p:entity}}/{id}
func (s *store) getTask(w http.ResponseWriter, r *http.Request, idStr string) {
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "invalid task id", http.StatusBadRequest)
		return
	}

	s.Lock()
	defer s.Unlock()

	for _, t := range s.{{p:entity}} {
		if t.ID == id {
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(t)
			return
		}
	}
	http.Error(w, "task not found", http.StatusNotFound)
}

// createTask handles POST /{{p:entity}}
func (s *store) createTask(w http.ResponseWriter, r *http.Request) {
	var payload struct {
		Title string `json:"title"`
	}
	if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
		http.Error(w, "invalid JSON payload", http.StatusBadRequest)
		return
	}
	if strings.TrimSpace(payload.Title) == "" {
		http.Error(w, "title is required", http.StatusBadRequest)
		return
	}

	s.Lock()
	defer s.Unlock()

	newTask := Task{
		ID:        s.nextID,
		Title:     payload.Title,
		Completed: false,
	}
	s.nextID++
	s.{{p:entity}} = append(s.{{p:entity}}, newTask)

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(newTask)
}

// deleteTask handles DELETE /{{p:entity}}/{id}
func (s *store) deleteTask(w http.ResponseWriter, r *http.Request, idStr string) {
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "invalid task id", http.StatusBadRequest)
		return
	}

	s.Lock()
	defer s.Unlock()

	for i, t := range s.{{p:entity}} {
		if t.ID == id {
			// Remove the task from the slice
			s.{{p:entity}} = append(s.{{p:entity}}[:i], s.{{p:entity}}[i+1:]...)
			w.WriteHeader(http.StatusNoContent)
			return
		}
	}
	http.Error(w, "task not found", http.StatusNotFound)
}

// router dispatches requests to the appropriate handler.
func (s *store) router(w http.ResponseWriter, r *http.Request) {
	// Trim leading/trailing slashes for easier matching
	path := strings.Trim(r.URL.Path, "/")
	parts := strings.Split(path, "/")

	// All endpoints start with "{{p:entity}}"
	if len(parts) == 0 || parts[0] != "{{p:entity}}" {
		http.NotFound(w, r)
		return
	}

	// /{{p:entity}}
	if len(parts) == 1 {
		switch r.Method {
		case http.MethodGet:
			s.list{{p:entity:title}}(w, r)
		case http.MethodPost:
			s.createTask(w, r)
		default:
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		}
		return
	}

	// /{{p:entity}}/{id}
	if len(parts) == 2 {
		id := parts[1]
		switch r.Method {
		case http.MethodGet:
			s.getTask(w, r, id)
		case http.MethodDelete:
			s.deleteTask(w, r, id)
		default:
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		}
		return
	}

	// Anything else is not found
	http.NotFound(w, r)
}

func main() {
	s := newStore()

	// Simple health check endpoint
	http.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprintln(w, "OK")
	})

	// All task‑related routes go through the store's router
	http.HandleFunc("/", s.router)

	addr := ":8080"
	log.Printf("Task API listening on %s", addr)
	if err := http.ListenAndServe(addr, nil); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
```

### How to run

1. **Save** the code above as `main.go`.
2. **Build** and run it:

   ```bash
   go run main.go
   ```

   The server will listen on `http://localhost:8080`.

### Example usage (with `curl`)

```bash
# Create a task
curl -X POST -d '{"title":"Buy milk"}' -H "Content-Type: application/json" http://localhost:8080/{{p:entity}}
# → {"id":1,"title":"Buy milk","completed":false}

# List all {{p:entity}}
curl http://localhost:8080/{{p:entity}}
# → [{"id":1,"title":"Buy milk","completed":false}]

# Get a single task
curl http://localhost:8080/{{p:entity}}/1
# → {"id":1,"title":"Buy milk","completed":false}

# Delete a task
curl -X DELETE http://localhost:8080/{{p:entity}}/1
# → (no content, HTTP 204)

# Verify deletion
curl http://localhost:8080/{{p:entity}}
# → []
```

The implementation is deliberately straightforward: it stores everything in memory, so all data is lost when the process stops. For production use you would replace the in‑memory store with a persistent database, add proper input validation, logging, graceful shutdown, etc. But this snippet fulfills the requested “simple REST API in Go that manages {{p:entity}} in memory (list, get, create, delete).”

Below is a complete **`main_test.go`** file that you can place next to the `main.go` implementation.  
It uses only the Go standard library (`testing`, `net/http/httptest`, `encoding/json`, `bytes`, `strconv`) and exercises all four API endpoints:

| Test | What it verifies |
|------|-------------------|
| `TestCreateTask` | `POST /{{p:entity}}` creates a task and returns **{{int:160:242}} Created** with the correct JSON payload. |
| `TestList{{p:entity:title}}` | `GET /{{p:entity}}` returns a JSON array containing the {{p:entity}} that were previously created. |
| `TestGetTask`   | `GET /{{p:entity}}/{id}` fetches a single task and returns **{{int:160:240}} OK** with the expected fields. |
| `TestDeleteTask`| `DELETE /{{p:entity}}/{id}` removes the task and subsequent `GET` returns **{{int:323:485}} Not Found**. |
| `TestInvalidMethods`| Requests with unsupported HTTP methods receive **{{int:324:486}} Method Not Allowed**. |
| `TestBadID`| Non‑numeric IDs and missing IDs return **{{int:320:480}} Bad Request**. |

```go
// File: main_test.go
package main

import (
	"bytes"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"testing"
)

// helper to perform a request against the router
func doRequest(s *store, method, path string, body io.Reader) *httptest.ResponseRecorder {
	req := httptest.NewRequest(method, path, body)
	// set Content-Type for POST requests that carry JSON
	if method == http.MethodPost {
		req.Header.Set("Content-Type", "application/json")
	}
	rr := httptest.NewRecorder()
	s.router(rr, req)
	return rr
}

// ---------------------------------------------------------------------------
// 1. Create a task
// ---------------------------------------------------------------------------
func TestCreateTask(t *testing.T) {
	s := newStore()

	payload := `{"title":"Write unit tests"}`
	rr := doRequest(s, http.MethodPost, "/{{p:entity}}", strings.NewReader(payload))

	if rr.Code != http.StatusCreated {
		t.Fatalf("expected status %d, got %d", http.StatusCreated, rr.Code)
	}

	var created Task
	if err := json.NewDecoder(rr.Body).Decode(&created); err != nil {
		t.Fatalf("failed to decode response: %v", err)
	}
	if created.ID != 1 {
		t.Errorf("expected ID 1, got %d", created.ID)
	}
	if created.Title != "Write unit tests" {
		t.Errorf("title mismatch: expected %q, got %q", "Write unit tests", created.Title)
	}
	if created.Completed {
		t.Errorf("new task should not be completed")
	}
}

// ---------------------------------------------------------------------------
// 2. List {{p:entity}} (after creating a few)
// ---------------------------------------------------------------------------
func TestList{{p:entity:title}}(t *testing.T) {
	s := newStore()
	// create two {{p:entity}}
	for i, title := range []string{"Task A", "Task B"} {
		payload := `{"title":"` + title + `"}`
		rr := doRequest(s, http.MethodPost, "/{{p:entity}}", strings.NewReader(payload))
		if rr.Code != http.StatusCreated {
			t.Fatalf("setup %d: create returned %d", i, rr.Code)
		}
	}

	rr := doRequest(s, http.MethodGet, "/{{p:entity}}", nil)
	if rr.Code != http.StatusOK {
		t.Fatalf("list returned %d, want %d", rr.Code, http.StatusOK)
	}

	var {{p:entity}} []Task
	if err := json.NewDecoder(rr.Body).Decode(&{{p:entity}}); err != nil {
		t.Fatalf("decode list response: %v", err)
	}
	if len({{p:entity}}) != 2 {
		t.Fatalf("expected 2 {{p:entity}}, got %d", len({{p:entity}}))
	}
	if {{p:entity}}[0].Title != "Task A" || {{p:entity}}[1].Title != "Task B" {
		t.Errorf("task titles not as expected: %+v", {{p:entity}})
	}
}

// ---------------------------------------------------------------------------
// 3. Get a single task
// ---------------------------------------------------------------------------
func TestGetTask(t *testing.T) {
	s := newStore()
	// create one task
	rr := doRequest(s, http.MethodPost, "/{{p:entity}}", strings.NewReader(`{"title":"Single task"}`))
	if rr.Code != http.StatusCreated {
		t.Fatalf("setup create failed: %d", rr.Code)
	}
	var created Task
	if err := json.NewDecoder(rr.Body).Decode(&created); err != nil {
		t.Fatalf("decode created task: %v", err)
	}

	// fetch it
	rr = doRequest(s, http.MethodGet, "/{{p:entity}}/"+strconv.Itoa(created.ID), nil)
	if rr.Code != http.StatusOK {
		t.Fatalf("get returned %d, want %d", rr.Code, http.StatusOK)
	}
	var fetched Task
	if err := json.NewDecoder(rr.Body).Decode(&fetched); err != nil {
		t.Fatalf("decode fetched task: %v", err)
	}
	if fetched != created {
		t.Errorf("fetched task differs from created: got %+v, want %+v", fetched, created)
	}
}

// ---------------------------------------------------------------------------
// 4. Delete a task
// ---------------------------------------------------------------------------
func TestDeleteTask(t *testing.T) {
	s := newStore()
	// create a task to delete
	rr := doRequest(s, http.MethodPost, "/{{p:entity}}", strings.NewReader(`{"title":"To be removed"}`))
	if rr.Code != http.StatusCreated {
		t.Fatalf("setup create failed: %d", rr.Code)
	}
	var created Task
	if err := json.NewDecoder(rr.Body).Decode(&created); err != nil {
		t.Fatalf("decode created task: %v", err)
	}

	// delete it
	rr = doRequest(s, http.MethodDelete, "/{{p:entity}}/"+strconv.Itoa(created.ID), nil)
	if rr.Code != http.StatusNoContent {
		t.Fatalf("delete returned %d, want %d", rr.Code, http.StatusNoContent)
	}

	// ensure it is gone
	rr = doRequest(s, http.MethodGet, "/{{p:entity}}/"+strconv.Itoa(created.ID), nil)
	if rr.Code != http.StatusNotFound {
		t.Fatalf("expected 404 after delete, got %d", rr.Code)
	}
}

// ---------------------------------------------------------------------------
// 5. Invalid method handling (405)
// ---------------------------------------------------------------------------
func TestInvalidMethods(t *testing.T) {
	s := newStore()
	tests := []struct {
		method string
		path   string
	}{
		{http.MethodPut, "/{{p:entity}}"},
		{http.MethodPatch, "/{{p:entity}}/1"},
		{http.MethodPost, "/{{p:entity}}/1"}, // POST on a specific ID is not allowed
	}
	for _, tt := range tests {
		rr := doRequest(s, tt.method, tt.path, nil)
		if rr.Code != http.StatusMethodNotAllowed {
			t.Errorf("%s %s: expected 405, got %d", tt.method, tt.path, rr.Code)
		}
	}
}

// ---------------------------------------------------------------------------
// 6. Bad ID handling (400)
// ---------------------------------------------------------------------------
func TestBadID(t *testing.T) {
	s := newStore()
	// non‑numeric ID
	rr := doRequest(s, http.MethodGet, "/{{p:entity}}/abc", nil)
	if rr.Code != http.StatusBadRequest {
		t.Errorf("GET non‑numeric ID: expected 400, got %d", rr.Code)
	}
	// delete with non‑numeric ID
	rr = doRequest(s, http.MethodDelete, "/{{p:entity}}/xyz", nil)
	if rr.Code != http.StatusBadRequest {
		t.Errorf("DELETE non‑numeric ID: expected 400, got %d", rr.Code)
	}
}
```

### How to run the tests

1. Make sure both `main.go` and `main_test.go` are in the same package directory.  
2. Run:

```bash
go test -v
```

You should see output similar to:

```
=== RUN   TestCreateTask
--- PASS: TestCreateTask (0.00s)
=== RUN   TestList{{p:entity:title}}
--- PASS: TestList{{p:entity:title}} (0.00s)
=== RUN   TestGetTask
--- PASS: TestGetTask (0.00s)
=== RUN   TestDeleteTask
--- PASS: TestDeleteTask (0.00s)
=== RUN   TestInvalidMethods
--- PASS: TestInvalidMethods (0.00s)
=== RUN   TestBadID
--- PASS: TestBadID (0.00s)
PASS
ok  	<module‑path>	0.XXXs
```

These tests give you confidence that the in‑memory task API behaves correctly for the required CRUD operations and proper error handling. Feel free to extend them (e.g., testing duplicate titles, concurrency, etc.) as your application evolves.
